/* Vayoo cookie consent. Generated by build/consent.py -- edit the generator. */
(function(){
'use strict';
var KEY='vayoo.consent.v1';
/* One shared file is served from several directory depths, so the link prefix
   is derived from the stylesheet href rather than baked in at build time. */
var ROOT=(function(){
  var l=document.querySelector('link[rel=stylesheet][href*="vayoo.css"]');
  return l?l.getAttribute('href').replace('assets/vayoo.css',''):'';
})();
var IDS={ga4:'',ads:'',pixel:''};

/* Google Consent Mode v2: deny everything BEFORE any Google tag can fire. */
window.dataLayer=window.dataLayer||[];
function gtag(){dataLayer.push(arguments);}
window.gtag=window.gtag||gtag;
gtag('consent','default',{
  ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied',
  analytics_storage:'denied',functionality_storage:'granted',
  security_storage:'granted',wait_for_update:500
});

function read(){try{return JSON.parse(localStorage.getItem(KEY));}catch(e){return null;}}
function write(v){try{localStorage.setItem(KEY,JSON.stringify(v));}catch(e){}}

var loaded={};
function script(src){
  if(loaded[src])return; loaded[src]=1;
  var s=document.createElement('script');s.async=true;s.src=src;
  document.head.appendChild(s);
}

function loadAnalytics(){
  if(!IDS.ga4)return;
  script('https://www.googletagmanager.com/gtag/js?id='+IDS.ga4);
  gtag('js',new Date()); gtag('config',IDS.ga4,{anonymize_ip:true});
}
function loadGoogleAds(){
  if(!IDS.ads)return;
  script('https://www.googletagmanager.com/gtag/js?id='+IDS.ads);
  gtag('js',new Date()); gtag('config',IDS.ads);
}
function loadMetaPixel(){
  if(!IDS.pixel||window.fbq)return;
  /* standard Meta base code, loaded only once advertising consent exists */
  !function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?
  n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;
  n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;
  t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}
  (window,document,'script','https://connect.facebook.net/en_US/fbevents.js');
  window.fbq('consent','grant');
  window.fbq('init',IDS.pixel);
  window.fbq('track','PageView');
}

function apply(c){
  gtag('consent','update',{
    ad_storage:c.ads?'granted':'denied',
    ad_user_data:c.ads?'granted':'denied',
    ad_personalization:c.ads?'granted':'denied',
    analytics_storage:c.analytics?'granted':'denied'
  });
  if(c.analytics)loadAnalytics();
  if(c.ads){loadGoogleAds();loadMetaPixel();}
  else if(window.fbq){try{window.fbq('consent','revoke');}catch(e){}}
  window.vayooConsent=c;
  document.dispatchEvent(new CustomEvent('vayoo:consent',{detail:c}));
}

/* ---------- UI ---------- */
var scrim,box,prefs,swA,swM;
function build(){
  scrim=document.createElement('div');scrim.className='cc-scrim';
  box=document.createElement('div');box.className='cc';
  box.setAttribute('role','dialog');box.setAttribute('aria-modal','false');
  box.setAttribute('aria-label','Cookie choices');
  box.innerHTML=
   '<h2>Before we load anything</h2>'+
   '<p>We would like to set cookies for advertising and measurement, including Google Ads '+
   'and the Meta Pixel. They are switched <b>off</b> right now and will stay off unless you '+
   'turn them on. Strictly necessary cookies keep the site working and cannot be switched off. '+
   'Read the <a href="'+ROOT+'cookies/">Cookie Policy</a> or '+
   '<a href="'+ROOT+'privacy/">Privacy Policy</a>.</p>'+
   '<div class="cc-prefs" id="ccPrefs">'+
     '<div class="cc-row"><span class="cc-sw"><input type="checkbox" checked disabled '+
       'aria-label="Strictly necessary cookies, always on"></span>'+
       '<div><h3>Strictly necessary</h3><p>Your theme choice and this consent record. '+
       'No tracking, never shared.</p></div></div>'+
     '<div class="cc-row"><span class="cc-sw"><input type="checkbox" id="ccA" '+
       'aria-label="Analytics cookies"></span>'+
       '<div><h3>Analytics</h3><p>Google Analytics, so we can see which pages are useful. '+
       'Aggregated, with IP anonymisation on.</p></div></div>'+
     '<div class="cc-row"><span class="cc-sw"><input type="checkbox" id="ccM" '+
       'aria-label="Advertising cookies"></span>'+
       '<div><h3>Advertising</h3><p>Google Ads and the Meta Pixel. Lets us measure ads and '+
       'show you Vayoo ads on other sites. This is the one that builds a profile.</p></div></div>'+
   '</div>'+
   '<div class="cc-acts">'+
     '<button class="btn btn-p" data-cc="all">Accept all</button>'+
     '<button class="btn btn-s" data-cc="reject">Reject all</button>'+
     '<button class="btn btn-g" data-cc="prefs">Choose</button>'+
   '</div>';
  document.body.appendChild(scrim);document.body.appendChild(box);
  prefs=box.querySelector('#ccPrefs');swA=box.querySelector('#ccA');swM=box.querySelector('#ccM');

  box.addEventListener('click',function(e){
    var b=e.target.closest('[data-cc]');if(!b)return;
    var k=b.dataset.cc;
    if(k==='prefs'&&!prefs.classList.contains('on')){
      prefs.classList.add('on');
      b.textContent='Save choices';
      return;
    }
    var c;
    if(k==='all')c={necessary:true,analytics:true,ads:true};
    else if(k==='reject')c={necessary:true,analytics:false,ads:false};
    else c={necessary:true,analytics:!!swA.checked,ads:!!swM.checked};
    c.ts=new Date().toISOString();c.v=1;
    write(c);apply(c);hide();
  });
}
function show(existing){
  if(!box)build();
  if(existing){swA.checked=!!existing.analytics;swM.checked=!!existing.ads;
    prefs.classList.add('on');
    var pb=box.querySelector('[data-cc="prefs"]');if(pb)pb.textContent='Save choices';}
  scrim.classList.add('on');box.classList.add('on');
}
function hide(){if(scrim)scrim.classList.remove('on');if(box)box.classList.remove('on');}

var saved=read();
if(saved&&saved.v===1){apply(saved);}
else{apply({necessary:true,analytics:false,ads:false});
     if(document.readyState==='loading')
       document.addEventListener('DOMContentLoaded',function(){show(null);});
     else show(null);}

/* Withdrawal must be as easy as giving -- footer link and a global. */
window.vayooCookieSettings=function(){show(read());};
document.addEventListener('click',function(e){
  var t=e.target.closest('[data-cookie-settings]');
  if(t){e.preventDefault();show(read());}
});
})();
